import java.util.HashMap;
import java.util.Map;

public class BankSystem {

    private Map<String, Account> accounts;

    public BankSystem() {
        this.accounts = new HashMap<>();
    }

    public void createAccount(String accountNumber, String username, double balance) {
        if (accounts.containsKey(accountNumber)) {
            System.out.println("Account with number " + accountNumber + " already exists.");
        } else {
            Account account = new Account(username, accountNumber, balance);
            accounts.put(accountNumber, account);
            System.out.println("Account created successfully.");
        }
    }

    public void deposit(String accountNumber, double amount) {
        if (accounts.containsKey(accountNumber)) {
            accounts.get(accountNumber).setBalance(accounts.get(accountNumber).getBalance() + amount);
            System.out.println("Deposit successful. New balance: " + accounts.get(accountNumber).getBalance());
        } else {
            System.out.println("Account not found.");
        }
    }

    public void withdraw(String accountNumber, double amount) {
        if (accounts.containsKey(accountNumber)) {
            if (accounts.get(accountNumber).getBalance() >= amount) {
                accounts.get(accountNumber).setBalance(accounts.get(accountNumber).getBalance() - amount);
                System.out.println("Withdrawal successful. New balance: " + accounts.get(accountNumber).getBalance());
            } else {
                System.out.println("Insufficient balance.");
            }
        } else {
            System.out.println("Account not found.");
        }
    }

    public void displayAccount(String accountNumber) {
        if (accounts.containsKey(accountNumber)) {
            Account account = accounts.get(accountNumber);
            System.out.println("Account Number: " + accountNumber);
            System.out.println("Username: " + account.getUsername());
            System.out.println("Balance: " + account.getBalance());
        } else {
            System.out.println("Account not found.");
        }
    }

    public static void main(String[] args) {
