                    String accountNumber = System.console().readLine();
                    System.out.print("Enter username: ");
                    String username = System.console().readLine();
                    System.out.print("Enter balance (0 to cancel): ");
                    double amount = Double.parseDouble(System.console().readLine());

                    if (amount == 0) {
                        break;
                    } else {
                        bank.createAccount(accountNumber, username, amount);
                    }
                    break;
                case 2:
