public class BankSystem {
    private int money;

    public BankSystem() {
        this.money = 1000;
    }

    public void deposit(int amount) {
        if (amount > 0) {
            money += amount;
            System.out.println("Deposit successful. New balance: " + money);
        } else {
            System.out.println("Invalid input.");
        }
    }

    public void withdraw(int amount) {
        if (amount > 0 && amount <= money) {
            money -= amount;
            System.out.println("Withdrawal successful. New balance: " + money);
        } else if (amount <= 0) {
            System.out.println("Invalid input.");
        } else {
            System.out.println("Insufficient balance or invalid input.");
        }
    }

    public void displayBalance() {
        System.out.println("Your current balance is: " + money);
    }

    public static void main(String[] args) {
        BankSystem bank = new BankSystem();

        while (true) {
            System.out.println("1. Deposit Money");
            System.out.println("2. Withdraw Money");
            System.out.println("3. Display Balance");
            System.out.println("4. Exit");

            System.out.print("Choose an option: ");
            int choice = Integer.parseInt(System.console().readLine());

            switch (choice) {
                case 1:
                    System.out.print("Enter amount to deposit: ");
                    int amount = Integer.parseInt(System.console().readLine());
                    bank.deposit(amount);
                    break;
                case 2:
                    System.out.print("Enter amount to withdraw: ");
                    if (bank.money >= Integer.parseInt(System.console().readLine())) {
                        bank.withdraw(Integer.parseInt(System.console().readLine()));
                    } else {
                        System.out.println("Insufficient balance.");
                    }
                    break;
                case 3:
                    bank.displayBalance();
                    break;
                case 4:
                    System.exit(0);
                    break;
                default:
                    System.out.println("Invalid option. Please choose a valid option.");
            }
        }
    }
}
